-- Esquema de la base Tienda (SQL Server)
CREATE TABLE dbo.DimProducto (
    ProductoID   INT PRIMARY KEY,
    Producto     NVARCHAR(100),
    Subcategoria NVARCHAR(50),
    Categoria    NVARCHAR(50),
    CostoUnit    DECIMAL(10,2)
);
CREATE TABLE dbo.DimCliente (ClienteID INT PRIMARY KEY, Cliente NVARCHAR(100), Ciudad NVARCHAR(50), Segmento NVARCHAR(20));
CREATE TABLE dbo.DimSucursal (SucursalID INT PRIMARY KEY, Sucursal NVARCHAR(50), Region NVARCHAR(30));
CREATE TABLE dbo.FactVentas (
    VentaID     BIGINT PRIMARY KEY,
    FechaVenta  DATE,
    ProductoID  INT REFERENCES dbo.DimProducto(ProductoID),
    ClienteID   INT REFERENCES dbo.DimCliente(ClienteID),
    SucursalID  INT REFERENCES dbo.DimSucursal(SucursalID),
    Cantidad    INT,
    PrecioUnit  DECIMAL(10,2),
    Descuento   DECIMAL(10,2)
);

// Parámetros (Administrar parámetros):
//   Servidor   = "srv-datos"      (texto)
//   BaseDatos  = "Tienda"         (texto)
//   RangeStart = #datetime(2025, 1, 1, 0, 0, 0)
//   RangeEnd   = #datetime(2026, 1, 1, 0, 0, 0)
let
    Origen = Sql.Database(Servidor, BaseDatos),
    Ventas = Origen{[Schema = "dbo", Item = "FactVentas"]}[Data],
    Rango  = Table.SelectRows(Ventas, each
               [FechaHoraVenta] >= RangeStart and [FechaHoraVenta] < RangeEnd)
in
    Rango

