CREATE TABLE rpt.PermisosRegion (
    Correo    NVARCHAR(256) NOT NULL,
    Region    NVARCHAR(30)  NOT NULL,
    FechaBaja DATE          NULL,
    CONSTRAINT PK_PermisosRegion PRIMARY KEY (Correo, Region)
);

INSERT INTO rpt.PermisosRegion (Correo, Region)
VALUES (N'jefa.norte@tienda.com', N'Norte'),
       (N'jefe.caribe@tienda.com', N'Caribe');

SELECT Correo, Region
FROM rpt.PermisosRegion
WHERE FechaBaja IS NULL
   OR FechaBaja > CAST(GETDATE() AS date);
